CREATE TABLE persona (id VARCHAR(36) PRIMARY KEY, project_id VARCHAR(36) NOT NULL REFERENCES project(id), name VARCHAR(100) NOT NULL, family VARCHAR(16) NOT NULL, definition TEXT NOT NULL, published_id VARCHAR(36), avatar TEXT, deleted BOOLEAN NOT NULL DEFAULT FALSE, creator VARCHAR(100) NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE persona_version (id VARCHAR(36) PRIMARY KEY, persona_id VARCHAR(36) NOT NULL REFERENCES persona(id), base_id VARCHAR(36), status VARCHAR(12) NOT NULL, content TEXT NOT NULL, creator VARCHAR(100) NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE persona_conversation (id VARCHAR(36) PRIMARY KEY, persona_id VARCHAR(36) NOT NULL REFERENCES persona(id), version_id VARCHAR(36) NOT NULL REFERENCES persona_version(id), user_id VARCHAR(100) NOT NULL REFERENCES app_user(id), title VARCHAR(160) NOT NULL, emotion TEXT NOT NULL, memory_enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at BIGINT NOT NULL);
CREATE TABLE persona_message (id VARCHAR(36) PRIMARY KEY, conversation_id VARCHAR(36) NOT NULL REFERENCES persona_conversation(id), role VARCHAR(12) NOT NULL, body TEXT NOT NULL, emotion TEXT, created_at BIGINT NOT NULL);
CREATE INDEX persona_message_context ON persona_message(conversation_id,created_at);
CREATE TABLE persona_memory (id VARCHAR(36) PRIMARY KEY, persona_id VARCHAR(36) NOT NULL REFERENCES persona(id), user_id VARCHAR(100) NOT NULL REFERENCES app_user(id), body VARCHAR(1000) NOT NULL, source_id VARCHAR(36) NOT NULL REFERENCES persona_message(id), status VARCHAR(12) NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX persona_memory_scope ON persona_memory(persona_id,user_id,status);
CREATE TABLE persona_job (id VARCHAR(36) PRIMARY KEY, persona_id VARCHAR(36) NOT NULL REFERENCES persona(id), conversation_id VARCHAR(36) REFERENCES persona_conversation(id), kind VARCHAR(16) NOT NULL, status VARCHAR(12) NOT NULL, payload TEXT NOT NULL, result TEXT, error_code VARCHAR(40), creator VARCHAR(100) NOT NULL, attempt INT NOT NULL DEFAULT 0, lease_token VARCHAR(36), lease_until BIGINT, created_at BIGINT NOT NULL);
CREATE INDEX persona_job_claim ON persona_job(status,created_at);
